I have been trying to run the code below but I facing challenges with the distance computation. Find the error after the code below.
library(rmr)
library(rhdfs)
kmeans.iter =
  function(points, distfun, ncenters = dim(centers)[1], centers = NULL) {
    from.dfs(mapreduce(input = points,
                         map =
                           if (is.null(centers)) {
                             function(k,v) keyval(sample(1:ncenters,1),v)}
                           else {
                             function(k,v) {
                               distances = apply(centers, 1, function(c) distfun(c,v))
                               keyval(centers[which.min(distances),], v)}},
                         reduce = function(k,vv) keyval(NULL, apply(do.call(rbind, vv), 2, mean))),
             to.data.frame = T)}

kmeans =
  function(points, ncenters, iterations = 10,
           distfun =
             function(a,b) norm(as.matrix(a-b), type = 'F')) {
    newCenters = kmeans.iter(points, distfun,
                             ncenters = ncenters)
    for(i in 1:iterations) {
      newCenters = lapply(values(newCenters), unlist)
      newCenters = kmeans.iter(points, distfun,
                               centers=newCenters)}
    newCenters}

out = list()
set.seed(0)
  input = to.dfs(lapply(1:1000, function(i) keyval(NULL, c(rnorm(1, mean = i%%3, sd = 0.1),
                                                         rnorm(1, mean = i%%4, sd = 0.1)))))
  out[[1]] = kmeans(input, 12, iterations = 5)
Error
